import React, { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { motion } from 'framer-motion';
import apiService from '../../services/api';
import AdminLayout from './AdminLayout';
import { ToastContainer } from '../../components/ui/Toast';

export default function AdminEditSong() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [toasts, setToasts] = useState([]);
  
  // Lists
  const [allArtists, setAllArtists] = useState([]);
  const [allAlbums, setAllAlbums] = useState([]);

  // Form State
  const [name, setName] = useState('');
  const [artists, setArtists] = useState([]); // array of IDs
  const [album, setAlbum] = useState(''); // ID
  const [trackNumber, setTrackNumber] = useState('');
  const [duration, setDuration] = useState('');
  const [spotifyId, setSpotifyId] = useState('');
  const [previewUrl, setPreviewUrl] = useState('');
  const [externalSpotifyUrl, setExternalSpotifyUrl] = useState('');
  const [popularity, setPopularity] = useState('');
  const [tags, setTags] = useState('');
  
  const [discNumber, setDiscNumber] = useState('1');
  const [explicit, setExplicit] = useState(false);
  const [category, setCategory] = useState('');
  const [genre, setGenre] = useState('');
  const [albumGenres, setAlbumGenres] = useState([]);
  const [mood, setMood] = useState('');
  const [language, setLanguage] = useState('');
  const [artistNames, setArtistNames] = useState('');
  
  // Current File URLs
  const [currentAudioUrl, setCurrentAudioUrl] = useState('');
  const [currentCoverUrl, setCurrentCoverUrl] = useState('');
  
  // File State
  const [audioFile, setAudioFile] = useState(null);
  const [coverFile, setCoverFile] = useState(null);
  const [lyricsFile, setLyricsFile] = useState(null);

  const showToast = (message, type = 'error', duration = 4000) => {
    const toastId = Date.now();
    setToasts(prev => [...prev, { id: toastId, message, type, duration }]);
  };

  const removeToast = (id) => {
    setToasts(prev => prev.filter(toast => toast.id !== id));
  };

  useEffect(() => {
    const loadData = async () => {
      try {
        const [res, artistsRes, albumsRes] = await Promise.all([
          apiService.getSong(id),
          apiService.getArtists(1, 1000),
          apiService.getAlbums(1, 1000)
        ]);
        
        const song = res.song || res;
        const artistsList = artistsRes.artists || (Array.isArray(artistsRes) ? artistsRes : []);
        setAllArtists(artistsList);
        setAllAlbums(albumsRes.albums || (Array.isArray(albumsRes) ? albumsRes : []));
        
        setName(song.name || '');
        setArtists(song.artists ? song.artists.map(a => a._id || a) : []);
        
        // Set artist names for display
        const songArtists = song.artists || [];
        const aNames = songArtists.map(a => {
           if (typeof a === 'object' && a.name) return a.name;
           const found = artistsList.find(ar => ar._id === a);
           return found ? found.name : '';
        }).filter(Boolean).join(', ');
        setArtistNames(aNames);

        setAlbum(song.album ? (song.album._id || song.album) : '');
        setAlbumGenres(song.album?.genres || []);
        setTrackNumber(song.track_number || '');
        setDuration(song.duration_ms ? Math.round(song.duration_ms / 1000) : '');
        setSpotifyId(song.spotify_id || '');
        setPreviewUrl(song.preview_url || '');
        setExternalSpotifyUrl(song.external_urls?.spotify || '');
        setPopularity(song.popularity || '');
        setTags(Array.isArray(song.tags) ? song.tags.join(', ') : (song.tags || ''));
        
        setDiscNumber(song.disc_number || '1');
        setExplicit(song.explicit || false);
        setCategory(song.category || '');
        setGenre(song.genre ? (song.genre.name || song.genre) : '');
        setMood(song.mood || '');
        setLanguage(song.language || '');
        
        setCurrentAudioUrl(song.audio_url || '');
        setCurrentCoverUrl(song.cover_art_url || song.album?.images?.[0]?.url || '');
      } catch (error) {
        console.error('Error loading data:', error);
        showToast('Error loading song details', 'error');
        navigate('/admin/songs');
      } finally {
        setLoading(false);
      }
    };
    loadData();
  }, [id, navigate]);

  const handleSave = async () => {
    if (!name.trim()) {
      showToast('Name is required', 'error');
      return;
    }

    setSaving(true);
    try {
      const formData = new FormData();
      formData.append('name', name.trim());
      
      if (artists.length > 0) formData.append('artists', JSON.stringify(artists));
      if (album) formData.append('album', album);
      if (trackNumber) formData.append('track_number', trackNumber);
      if (duration) formData.append('duration', duration);
      if (spotifyId) formData.append('spotify_id', spotifyId);
      if (previewUrl) formData.append('preview_url', previewUrl);
      if (externalSpotifyUrl) formData.append('external_urls.spotify', externalSpotifyUrl);
      if (popularity) formData.append('popularity', popularity);
      if (tags) formData.append('tags', tags);

      formData.append('disc_number', discNumber);
      formData.append('explicit', explicit);
      if (category) formData.append('category', category);
      if (genre) formData.append('genre', genre);
      if (mood) formData.append('mood', mood);
      if (language) formData.append('language', language);

      if (audioFile) formData.append('audio', audioFile);
      if (coverFile) formData.append('cover', coverFile);
      if (lyricsFile) formData.append('lyricsFile', lyricsFile);

      await apiService.updateSong(id, formData);
      showToast('Song updated successfully', 'success');
      setTimeout(() => navigate('/admin/songs'), 1000);
    } catch (error) {
      console.error('Error updating song:', error);
      // Try to get the detailed error from backend
      const detail = error.details?.error || error.details?.message || error.message;
      showToast(`Failed to update song: ${detail}`, 'error');
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <AdminLayout>
        <div className="flex items-center justify-center h-64 text-gray-400">Loading...</div>
      </AdminLayout>
    );
  }

  return (
    <AdminLayout>
      <ToastContainer toasts={toasts} removeToast={removeToast} />
      <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="max-w-4xl mx-auto">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-2xl font-bold text-white">Edit Song</h2>
          <button onClick={() => navigate('/admin/songs')} className="px-4 py-2 rounded-lg bg-gray-700 text-white hover:bg-gray-600">
            Back to List
          </button>
        </div>

        <div className="bg-dark-gray/40 rounded-xl border border-gray-800 p-6 space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-4">
              <div>
                <label className="block text-sm text-gray-400 mb-1">Name *</label>
                <input 
                  value={name} 
                  onChange={e => setName(e.target.value)}
                  className="w-full px-4 py-2 rounded-lg bg-light-gray/50 text-white border border-gray-700 focus:border-neon-blue focus:outline-none" 
                  placeholder="Song Name"
                />
              </div>

              <div>
                <label className="block text-sm text-gray-400 mb-1">Album</label>
                <select 
                  value={album} 
                  onChange={e => {
                    const selectedAlbumId = e.target.value;
                    setAlbum(selectedAlbumId);
                    const selectedAlbum = allAlbums.find(item => item._id === selectedAlbumId);
                    setAlbumGenres(selectedAlbum?.genres || []);
                  }}
                  className="w-full px-4 py-2 rounded-lg bg-light-gray/50 text-white border border-gray-700 focus:border-neon-blue focus:outline-none appearance-none"
                >
                  <option value="">Select Album</option>
                  {allAlbums.map(a => (
                    <option key={a._id} value={a._id}>{a.name}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm text-gray-400 mb-1">Artists</label>
                <select
                  multiple
                  value={artists}
                  onChange={e => {
                    const values = Array.from(e.target.selectedOptions).map(option => option.value);
                    const names = values
                      .map(value => allArtists.find(artist => artist._id === value)?.name)
                      .filter(Boolean)
                      .join(', ');
                    setArtists(values);
                    setArtistNames(names);
                  }}
                  className="w-full min-h-[140px] px-4 py-2 rounded-lg bg-light-gray/50 text-white border border-gray-700 focus:border-neon-blue focus:outline-none"
                >
                  {allArtists.map((artist) => (
                    <option key={artist._id} value={artist._id}>
                      {artist.name}
                    </option>
                  ))}
                </select>
                <p className="text-xs text-gray-500 mt-2">Hold `Ctrl` or `Cmd` to select multiple artists.</p>
                {artistNames && <p className="text-xs text-gray-400 mt-1">Selected: {artistNames}</p>}
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm text-gray-400 mb-1">Track Number</label>
                  <input
                    type="number"
                    min="1"
                    value={trackNumber}
                    onChange={e => setTrackNumber(e.target.value)}
                    className="w-full px-4 py-2 rounded-lg bg-light-gray/50 text-white border border-gray-700 focus:border-neon-blue focus:outline-none"
                    placeholder="1"
                  />
                </div>
                <div>
                  <label className="block text-sm text-gray-400 mb-1">Duration (seconds)</label>
                  <input
                    type="number"
                    min="0"
                    value={duration}
                    onChange={e => setDuration(e.target.value)}
                    className="w-full px-4 py-2 rounded-lg bg-light-gray/50 text-white border border-gray-700 focus:border-neon-blue focus:outline-none"
                    placeholder="215"
                  />
                </div>
              </div>
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-sm text-gray-400 mb-1">Preview URL</label>
                <input 
                  value={previewUrl} 
                  onChange={e => setPreviewUrl(e.target.value)} 
                  className="w-full px-4 py-2 rounded-lg bg-light-gray/50 text-white border border-gray-700 focus:border-neon-blue focus:outline-none" 
                  placeholder="https://..."
                />
              </div>

              <div>
                <label className="block text-sm text-gray-400 mb-1">Popularity</label>
                <input 
                  type="number"
                  min="0"
                  max="100"
                  value={popularity} 
                  onChange={e => setPopularity(e.target.value)} 
                  className="w-full px-4 py-2 rounded-lg bg-light-gray/50 text-white border border-gray-700 focus:border-neon-blue focus:outline-none" 
                  placeholder="0-100"
                />
              </div>

              <div>
                <label className="block text-sm text-gray-400 mb-1">Tags (comma separated)</label>
                <input 
                  value={tags} 
                  onChange={e => setTags(e.target.value)} 
                  className="w-full px-4 py-2 rounded-lg bg-light-gray/50 text-white border border-gray-700 focus:border-neon-blue focus:outline-none" 
                  placeholder="hit, single, acoustic"
                />
              </div>

              <div>
                <label className="block text-sm text-gray-400 mb-1">Category</label>
                <input 
                  value={category} 
                  onChange={e => setCategory(e.target.value)} 
                  className="w-full px-4 py-2 rounded-lg bg-light-gray/50 text-white border border-gray-700 focus:border-neon-blue focus:outline-none" 
                  placeholder="e.g. Pop"
                />
              </div>

              <div>
                <label className="block text-sm text-gray-400 mb-1">Genre</label>
                <div className="flex gap-2">
                  <input 
                    value={genre} 
                    onChange={e => setGenre(e.target.value)} 
                    className="flex-1 px-4 py-2 rounded-lg bg-light-gray/50 text-white border border-gray-700 focus:border-neon-blue focus:outline-none" 
                    placeholder="e.g. Synth-pop"
                  />
                  {albumGenres.length > 0 && genre !== albumGenres[0] && (
                    <button 
                      onClick={() => setGenre(albumGenres[0])}
                      className="px-3 py-1 text-[10px] bg-neon-blue/20 text-neon-blue rounded border border-neon-blue/30 hover:bg-neon-blue/30 transition-colors"
                      title={`Use album's primary genre: ${albumGenres[0]}`}
                    >
                      Use Album Genre
                    </button>
                  )}
                </div>
                {albumGenres.length > 0 && (
                   <div className="mt-1 flex flex-wrap gap-1">
                      <span className="text-[10px] text-gray-500 mr-1">Album Genres:</span>
                      {albumGenres.map(g => (
                        <span key={g} className="text-[10px] text-gray-400 bg-gray-800 px-1 rounded">{g}</span>
                      ))}
                   </div>
                )}
              </div>

              <div>
                <label className="block text-sm text-gray-400 mb-1">Mood</label>
                <input 
                  value={mood} 
                  onChange={e => setMood(e.target.value)} 
                  className="w-full px-4 py-2 rounded-lg bg-light-gray/50 text-white border border-gray-700 focus:border-neon-blue focus:outline-none" 
                  placeholder="e.g. Happy"
                />
              </div>

              <div>
                <label className="block text-sm text-gray-400 mb-1">Language</label>
                <input 
                  value={language} 
                  onChange={e => setLanguage(e.target.value)} 
                  className="w-full px-4 py-2 rounded-lg bg-light-gray/50 text-white border border-gray-700 focus:border-neon-blue focus:outline-none" 
                  placeholder="e.g. English"
                />
              </div>

              <div className="pt-2">
                 <label className="flex items-center gap-3 cursor-pointer">
                   <input 
                     type="checkbox" 
                     checked={explicit} 
                     onChange={e => setExplicit(e.target.checked)} 
                     className="w-5 h-5 rounded bg-gray-700 border-gray-600 text-neon-blue focus:ring-neon-blue" 
                   />
                   <span className="text-white">Explicit Content</span>
                 </label>
              </div>

              <div className="pt-4 space-y-4 border-t border-gray-800 mt-4">
                <div>
                  <div className="flex items-center justify-between mb-1">
                    <label className="block text-sm text-gray-400">Audio File</label>
                    {currentAudioUrl ? (
                      <span className="text-[10px] text-green-400 border border-green-400/50 px-1 rounded flex items-center gap-1">
                        <svg className="w-2 h-2" fill="currentColor" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>
                        Already Uploaded
                      </span>
                    ) : (
                      <span className="text-[10px] text-orange-400 border border-orange-400/50 px-1 rounded">No Audio</span>
                    )}
                  </div>
                  <input 
                    type="file" 
                    accept="audio/*" 
                    onChange={e => setAudioFile(e.target.files[0])} 
                    className="w-full text-sm text-gray-300 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-neon-blue/10 file:text-neon-blue hover:file:bg-neon-blue/20" 
                  />
                  {currentAudioUrl && (
                    <div className="mt-1 text-xs text-gray-500 truncate max-w-xs">
                      Current: {currentAudioUrl.split('/').pop()}
                    </div>
                  )}
                </div>
                <div>
                  <div className="flex items-center justify-between mb-1">
                    <label className="block text-sm text-gray-400">Cover Image</label>
                    {currentCoverUrl ? (
                      <span className="text-[10px] text-green-400 border border-green-400/50 px-1 rounded">Has Cover</span>
                    ) : (
                      <span className="text-[10px] text-orange-400 border border-orange-400/50 px-1 rounded">No Cover</span>
                    )}
                  </div>
                  <input 
                    type="file" 
                    accept="image/*" 
                    onChange={e => setCoverFile(e.target.files[0])} 
                    className="w-full text-sm text-gray-300 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-neon-blue/10 file:text-neon-blue hover:file:bg-neon-blue/20" 
                  />
                </div>
                <div>
                  <label className="block text-sm text-gray-400 mb-1">Lyrics File</label>
                  <input 
                    type="file" 
                    accept=".lrc,.txt" 
                    onChange={e => setLyricsFile(e.target.files[0])} 
                    className="w-full text-sm text-gray-300 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-neon-blue/10 file:text-neon-blue hover:file:bg-neon-blue/20" 
                  />
                </div>
              </div>
            </div>
          </div>

          <div className="flex justify-end gap-3 pt-4 border-t border-gray-800">
            <button 
              onClick={() => navigate('/admin/songs')} 
              className="px-6 py-2 rounded-lg bg-gray-700 text-white hover:bg-gray-600 transition-colors"
            >
              Cancel
            </button>
            <button 
              onClick={handleSave} 
              disabled={saving}
              className="px-6 py-2 rounded-lg bg-neon-blue text-dark-bg font-medium hover:bg-neon-blue/80 transition-colors disabled:opacity-50"
            >
              {saving ? 'Saving...' : 'Save Changes'}
            </button>
          </div>
        </div>
      </motion.div>
    </AdminLayout>
  );
}
